#!/usr/bin/env python3
"""Screen lead-maintained main T2 rows; no status edits. Run from repo root."""
import csv, re, subprocess
from pathlib import Path
skip = set('8002AEE4 80017378 8002F45C 80015F6C 8001E0B4 8001AA90 80023EF0 80018F20 80024714 8002B22C 800287D4 80012390 800191F0 8002A4F0 8001BB64 8001D47C'.split())
private = set('80037A30 80037A6C 80037C3C 8003846C 80038EA4 8003D71C 8003D9BC 8003E1DC 8003FB20 800405E4 800407B4 80040A4C 800414F8 80041978 800419C8'.split())
candidates = {'80037780':'SDK _bnkfPatchInst: flags + sound array + inlined wave relocation', '80038DE0':'SDK __getTrackByte: 0xFE escape/backreference and 16 tracks', '80039C08':'SDK alAudioFrame: earliest client callback, 16-sample quantization, filter commands', '8003EF90':'SDK alFxNew: six presets, delay/chorus/lowpass allocations', '80042198':'SDK alFxParamHdl: parameter dispatch; pre-existing T-035 identification', '8002AB90':'Possible demo amCreateAudioMgr derivative: audio heap, DMA list, three frames, thread', '8002B034':'Possible demo __amHandleFrameMsg derivative: AI length, command list, RSP task', '8002B1EC':'Possible demo __amHandleDoneMsg derivative: AI state/underrun handling'}
out=['# T-075 complete main T2 screen', '', 'Generated by `sweep.py`. Screening is signature triage, not a matching or provenance proof. The original removed alFxNew draft is read from HEAD. SDK call names alone are not SDK identity evidence. No new hidden gu/os candidate survived the screen.', '', '| Function | Disposition / signature | SDK calls in draft | Floating literals |', '|---|---|---|---|']
n=0
for r in csv.reader(open('tools/progress/status.csv')):
 if not r or not r[0].startswith('main:') or r[1]!='T2':continue
 n+=1;addr=r[0].split('0x')[1];name='func_'+addr
 ps=list(Path('tools/scratch/nonmatching').glob('T-*/'+name+'.c'))
 if ps:s=ps[0].read_text()
 elif addr=='8003EF90':s=subprocess.check_output(['git','show','HEAD:tools/scratch/nonmatching/T-026/func_8003EF90.c'],text=True)
 else:raise RuntimeError(name)
 calls=sorted(set(re.findall(r'\b((?:gu|os|al|__)[A-Za-z0-9_]+)\s*\(',s)))
 floats=sorted(set(re.findall(r'(?<![\w.])\d+\.\d+(?:[eE][-+]?\d+)?[fF]?',re.sub(r'/\*.*?\*/','',s,flags=re.S))))
 if addr in skip:why='SKIP: reserved to T-072'
 elif addr in private:why='SKIP: documented private libaudio ABI'
 elif addr in candidates:why=candidates[addr]
 elif 0x80031050<=int(addr,16)<=0x800327E8:why='Decoder / pixel kernel; private state, arithmetic coding or computed stores; no SDK identification'
 elif int(addr,16)>=0x8002E4A0 and int(addr,16)<0x80030000:why='Game sound player/event logic; SDK calls but custom state; no source identity'
 elif calls:why='Game rendering / audio / initialization using SDK APIs; no source identity'
 elif floats:why='Game effects / transforms; game globals and literals, no SDK matrix helper signature'
 else:why='Game state / asset / drawing logic; no SDK signature identified'
 out.append(f'| {name} | {why} | {", ".join(calls) or "—"} | {", ".join(floats) or "—"} |')
out.insert(2,f'**{n} starting T2 rows screened; {len(skip)} reserved to T-072 and {len(private)} documented private-ABI audio rows skipped for implementation.**')
Path('tools/scratch/nonmatching/T-075/SCREEN.md').write_text('\n'.join(out)+'\n')
print(n)
